CREATE TABLE "Template" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "sourceFilename" TEXT NOT NULL, "sourceFormat" TEXT NOT NULL DEFAULT 'spectora-html-text', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Template_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Section" ("id" TEXT NOT NULL, "title" TEXT NOT NULL, "position" INTEGER NOT NULL, "templateId" TEXT NOT NULL, CONSTRAINT "Section_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Item" ("id" TEXT NOT NULL, "title" TEXT NOT NULL, "position" INTEGER NOT NULL, "sectionId" TEXT NOT NULL, CONSTRAINT "Item_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Comment" ("id" TEXT NOT NULL, "html" TEXT NOT NULL, "plainText" TEXT NOT NULL, "position" INTEGER NOT NULL, "itemId" TEXT NOT NULL, CONSTRAINT "Comment_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ImportAudit" ("id" TEXT NOT NULL, "sourceFilename" TEXT NOT NULL, "sourceSha256" TEXT NOT NULL, "stats" JSONB NOT NULL, "warnings" JSONB NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "templateId" TEXT NOT NULL, CONSTRAINT "ImportAudit_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Section_templateId_position_key" ON "Section"("templateId", "position"); CREATE UNIQUE INDEX "Item_sectionId_position_key" ON "Item"("sectionId", "position"); CREATE UNIQUE INDEX "Comment_itemId_position_key" ON "Comment"("itemId", "position");
ALTER TABLE "Section" ADD CONSTRAINT "Section_templateId_fkey" FOREIGN KEY ("templateId") REFERENCES "Template"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Item" ADD CONSTRAINT "Item_sectionId_fkey" FOREIGN KEY ("sectionId") REFERENCES "Section"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Comment" ADD CONSTRAINT "Comment_itemId_fkey" FOREIGN KEY ("itemId") REFERENCES "Item"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "ImportAudit" ADD CONSTRAINT "ImportAudit_templateId_fkey" FOREIGN KEY ("templateId") REFERENCES "Template"("id") ON DELETE CASCADE ON UPDATE CASCADE;
